# Class definition
class Car:
    def __init__(self, brand, color):
        # Properties (attributes)
        self.brand = brand
        self.color = color
        self.speed = 0

    # Methods (behavior)
    def start(self):
        print(f"{self.brand} car has started")

    def accelerate(self, value):
        self.speed += value
        print(f"{self.brand} speed is now {self.speed} km/h")

class Student:
    def __init__(self, name, roll_no):
        self.name = name
        self.roll_no = roll_no
        self.marks = 0   # initially marks = 0

    def add_marks(self, value):
        self.marks += value # self.marks=self.marks+value =0+35=35

    def display_info(self):
        print("Name:", self.name)
        print("Roll No:", self.roll_no)
        print("Marks:", self.marks)

class BankAccount:
    def __init__(self, account_holder, initial_balance):
        self.account_holder = account_holder      # public
        self.__balance = initial_balance           # private (encapsulated)

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self.__balance += amount

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > self.__balance:
            raise ValueError("Insufficient balance")
        self.__balance -= amount

    def get_balance(self):
        return self.__balance

## parent class
class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print("Animal makes a sound")

## child class

class Dog(Animal):
    def speak(self):
        print(f"{self.name} says: Bark")

class Shape:
    def calculateArea(self):
        pass
class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def calculateArea(self):# same method
        return 3.14 * self.radius * self.radius #behaviour diff( Circle area)


class Rectangle(Shape):
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def calculateArea(self):
        return self.length * self.width


class Triangle(Shape):
    def __init__(self, base, height):
        self.base = base
        self.height = height

    def calculateArea(self):
        return 0.5 * self.base * self.height


shapes = [
    Circle(5),
    Rectangle(10, 4),
    Triangle(6, 8)
]

for shape in shapes:
    print(shape.calculateArea())

from abc import ABC, abstractmethod

class Shape(ABC):

    @abstractmethod
    def area(self):
        pass

class Device:
  def __init__(self, brand, model):
    self.brand=brand
    self.model=model

  def show_device_info(self):
    print("Brand:", self.brand)
    print("Model:", self.model)

class laptop(Device):
  def __init__(self, brand, model, battery_life):
    super().__init__(brand, model)
    self.battery_life=battery_life

  def show_laptop_info(self):
    self.show_device_info()
    print("Battery Life:", self.battery_life, "hours")

class MobilePhone(Device):
  def __init__(self, brand, model, camera_quality):
    super().__init__(brand, model)
    self.camera_quality=camera_quality

  def show_mobile_phone_info(self):
    self.show_device_info()
    print("Camera Quality:", self.camera_quality, "MP")

# Import required modules for abstraction
from abc import ABC, abstractmethod


# Abstract base class
class Payment(ABC):

    # Abstract method (no implementation here)
    @abstractmethod
    def pay(self):
        pass
        # This method must be implemented by all child classes


# Child class 1
class CreditCardPayment(Payment):

    # Implementing abstract method
    def pay(self):
        print("Payment done using Credit Card")


# Child class 2
class UpiPayment(Payment):

    # Implementing abstract method
    def pay(self):
        print("Payment done using UPI")

# Base class
class Animal:
    def sound(self):
        print("Animal makes a sound")


# Child class 1
class Dog(Animal):
    def sound(self):
        print("Dog barks")


# Child class 2
class Cat(Animal):
    def sound(self):
        print("Cat meows")


# Child class 3
class Cow(Animal):
    def sound(self):
        print("Cow moos")
